-- V39: el título comparable, para encontrar lo duplicado.
--
-- # Qué cambia
--
-- El filtro "Duplicados" de la biblioteca buscaba dos registros con el mismo
-- contenido, y las copias exactas no entran al importar: casi nunca
-- tenía nada que enseñar. Se decidió que enseñe lo que la
-- gente llama duplicado -mismo título y mismo autor, con distinto contenido-, que
-- es además la primera queja de quien usa Calibre.
--
-- # Por qué una columna guardada y no una generada
--
-- Se probó con una columna generada virtual, como `contributors.name_key`, y
-- sobre la biblioteca real el recuento tardaba 600 ms: SQLite recalcula la
-- expresión cada vez que lee la columna, también desde un índice que la
-- contiene. Guardada y mantenida por dos disparadores, el mismo recuento cuesta
-- unos 100 ms. La clave es la misma de V38 -minúsculas, sin tildes, sin espacios
-- de sobra- y sale de `db::catalog::clave_de_nombre_sql`; una prueba exige que
-- las tres expresiones de aquí sean las suyas.
--
-- Los disparadores escriben solo `title_key`, así que no despiertan a los que
-- miran el título o la fecha de modificación: ni el catálogo de búsqueda ni
-- `updated_at` ven un cambio que no hubo.
--
-- Contrato: docs/architecture/storage.md, sección 2.3.

ALTER TABLE editions ADD COLUMN title_key TEXT;

UPDATE editions SET title_key = lower(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(trim(title), '  ', ' '), '  ', ' '), 'á', 'a'), 'à', 'a'), 'â', 'a'), 'ä', 'a'), 'ã', 'a'), 'å', 'a'), 'ā', 'a'), 'ą', 'a'), 'ă', 'a'), 'Á', 'a'), 'À', 'a'), 'Â', 'a'), 'Ä', 'a'), 'Ã', 'a'), 'Å', 'a'), 'Ā', 'a'), 'Ą', 'a'), 'Ă', 'a'), 'é', 'e'), 'è', 'e'), 'ê', 'e'), 'ë', 'e'), 'ē', 'e'), 'ę', 'e'), 'ě', 'e'), 'ė', 'e'), 'É', 'e'), 'È', 'e'), 'Ê', 'e'), 'Ë', 'e'), 'Ē', 'e'), 'Ę', 'e'), 'Ě', 'e'), 'Ė', 'e'), 'í', 'i'), 'ì', 'i'), 'î', 'i'), 'ï', 'i'), 'ī', 'i'), 'į', 'i'), 'ı', 'i'), 'Í', 'i'), 'Ì', 'i'), 'Î', 'i'), 'Ï', 'i'), 'Ī', 'i'), 'Į', 'i'), 'İ', 'i'), 'ó', 'o'), 'ò', 'o'), 'ô', 'o'), 'ö', 'o'), 'õ', 'o'), 'ø', 'o'), 'ō', 'o'), 'ő', 'o'), 'Ó', 'o'), 'Ò', 'o'), 'Ô', 'o'), 'Ö', 'o'), 'Õ', 'o'), 'Ø', 'o'), 'Ō', 'o'), 'Ő', 'o'), 'ú', 'u'), 'ù', 'u'), 'û', 'u'), 'ü', 'u'), 'ū', 'u'), 'ů', 'u'), 'ű', 'u'), 'ų', 'u'), 'Ú', 'u'), 'Ù', 'u'),